void generate_spiral_matrix(int n,int matrix[][8]){int top;int bottom;int left;int right;int value;int i;top=0;bottom=n-1;left=0;right=n-1;value=1;while(top<=bottom&&left<=right){for(i=left;i<=right;i=i+1)matrix[top][i]=value++;top=top+1;for(i=top;i<=bottom;i=i+1)matrix[i][right]=value++;right=right-1;if(top<=bottom){for(i=right;i>=left;i=i-1)matrix[bottom][i]=value++;bottom=bottom-1;}if(left<=right){for(i=bottom;i>=top;i=i-1)matrix[i][left]=value++;left=left+1;}}}
int main(void){int m[8][8];generate_spiral_matrix(3,m);if(m[0][0]!=1||m[0][2]!=3||m[1][1]!=9||m[2][0]!=7)return 1;generate_spiral_matrix(1,m);if(m[0][0]!=1)return 2;return 42;}
